/**
 * Drizzle schema barrel.
 *
 * Each table lives in its own module next to this file and is re-exported
 * here, so `drizzle.config.ts` has a single entry point to load.
 *
 * The `courses` module holds the LMS tables (`courses`, `modules`,
 * `lectures`) that back the catalog and the course builder.
 *
 * The `auth` module holds the Better Auth tables (`users`, `sessions`,
 * `accounts`, `verifications`). It is generated by the Better Auth CLI and
 * must be regenerated whenever the auth config or its plugins change:
 *
 *   pnpm dlx auth@1.7.11 generate --config server/utils/auth.ts \
 *     --output server/db/schema/auth.ts -y
 */
export * from './auth'
export * from './courses'
